      "无尽绿潮": "Marée Verte Infinie",
      "每个敌方行动回合，在空位免费召唤2个普通哥布林。": "À chaque tour d'action ennemi, invoquer 2 gobelins ordinaires dans les emplacements vides gratuitement.",
      "丰穗战母·布蕾娅": "Mère de Guerre de la Moisson Breya",
