      "守护熊族新家园的战母。每回合召唤丰穗近卫，每3回合强化场上全部熊族。": "La mère de guerre qui garde le nouveau foyer des ours. Invoque une Garde de la Moisson chaque tour, et chaque 3 tours renforce tous les ours sur le champ de bataille.",
      "护田战令": "Décret du Garde des Champs",
      "每个敌方行动回合召唤1个5攻/7血的丰穗近卫。": "À chaque tour d'action ennemi, invoquer une Garde de la Moisson 5/7.",
      "丰收之怒": "Courroux de la Moisson",
      "每3个敌方行动回合，使场上所有熊族随从获得+1/+2。": "Tous les 3 tours d'action ennemis, donner à tous les serviteurs ours sur le champ de bataille +1/+2.",
      "碧露大贤者·涅芙莉": "Grande Sage Nephrie de la Rosée Azure",
      "梦幻森林的史莱姆引路者": "Guide de Gelée de la Forêt du Rêve",
      "拒绝离开故土的大贤者。每个行动回合恢复首领和全部史莱姆生命，每3回合分裂出两名碧露近卫。": "Une grande sage qui refuse de quitter sa patrie. À chaque tour d'action elle se soigne et soigne toutes les gelées, et tous les 3 tours divise deux Gardes de la Rosée Azure.",
      "不灭胶质": "Gelée Immortelle",
      "每个敌方行动回合，为首领恢复10点生命，并为所有史莱姆随从恢复5点生命。": "À chaque tour d'action ennemi, restaurer 10 Vie au boss et 5 Vie à tous les serviteurs de gelée.",
      "碧露分裂": "Division de la Rosée Azure",
      "每3个敌方行动回合，免费召唤2个4攻/12血碧露近卫。": "Tous les 3 tours d'action ennemis, invoquer 2 Gardes de la Rosée Azure 4/12 gratuitement.",
      "森林狼王": "Roi Loup de la Forêt",
      "裂月之牙": "Croc de la Lune Déchirée",
      "每3回合召唤幼狼；每4回合发动狼王咆哮。": "Invoque un Petit Loup tous les 3 tours ; déchaîne le Hurlement du Roi Loup tous les 4 tours.",
      "狼王号令": "Commandement du Roi Loup",
      "每3个敌方回合，在空位免费召唤1只幼狼。": "Tous les 3 tours ennemis, invoquer 1 Petit Loup dans un emplacement vide gratuitement.",
      "裂月咆哮": "Hurlement de la Lune Déchirée",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "Tous les 4 tours ennemis, tous les serviteurs loups gagnent définitivement +1 Attaque.",
      "银灰狼女猎手": "Chasseuse Loup Gris Argenté",
      "千枝城的灰牙首领": "Chef Greyfang de la Cité aux Mille Branches",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "La cheftaine loup qui a échappé aux poursuivants de la Cité d'Émeraude et a saisi les ruines de la Cité aux Mille Branches. À chaque tour elle appelle un loup gris rapide au combat.",
      "灰狼增援": "Renforts des Loups Gris",
      "每个敌方行动回合，召唤1只4攻/1血、可立即攻击随从的突击灰狼。": "À chaque tour d'action ennemi, invoquer un Loup Gris d'Assaut 4/1 qui peut attaquer les serviteurs immédiatement.",
      "千枝城魔族军官团": "Corps d'Officiers Démoniaques de la Cité aux Mille Branches",
      "拒绝退避的重建者": "Reconstructeurs qui Refusent de Battre en Retraite",
      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "La forteresse démoniaque stationnée à la Cité aux Mille Branches après l'histoire du Chapitre 5. Tous les serviteurs sont 20/200 — contenu de défi à long terme.",
      "千枝城驻军": "Garnison de la Cité aux Mille Branches",
      "使用20攻/200血的魅魔、龙族与开智战兽压制战场。": "Submerge le champ de bataille avec 20/200 succubes, draconiques et bêtes de guerre réveillées.",
