      "最后一击不算数。你的后排无人可守——重整阵线，再来。": "Le coup final ne compte pas. Personne n'est resté pour garder votre seconde ligne—regroupez-vous et réessayez.",
      "哈罗德挡下致命一击：我方后排没有存活的远程随从，试炼尚未完成。": "Harold pare le coup fatal: aucun serviteur à distance ne survit dans votre seconde ligne ; l'épreuve n'est pas complète.",
