      "你把火焰瓶砸向盾阵中央，烈焰没有伤到罗德里克，却令八面盾牌同时失去秩序。斩首窗口已经出现。": "Vous lancez le Flacon de Feu au centre de la formation de boucliers. Les flammes ne touchent pas Roderick, mais les huit boucliers se désorganisent tous à la fois. L'occasion de le vaincre est venue.",
