      "生命": "Vie",
      "战场上没有狼类随从，技能未强化任何单位。": "Il n'y a pas de serviteurs loups sur le champ de bataille ; la compétence n'a renforcé aucune unité.",
      "🐺 狼王咆哮发动！": "🐺 Rugissement du Roi Loup déchaîné !",
      "接管战场，准备主动反击": "Prenez le contrôle du champ de bataille et préparez-vous à frapper en retour",
      "封锁全部前排": "Scellez toute la première ligne",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "Les quatre officières succubes refusent de se retirer et ripostent à la fois avec 20 d'Attaque ; l'escouade sera repoussée, mais le Chapitre 5 compte toujours comme complété.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "Les quatre officières succubes n'attaquent pas ; elles maintiennent seulement la barrière, gagnant deux tours pour l'évasion de leur camarade.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "La riposte de la Cité aux Mille Branches commence : les quatre officières succubes frappent l'escouade une par une avec 20 d'Attaque.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "L'assaut des quatre officières brise la ligne, et l'avant-garde de l'Alliance démoniaque franchit la faille pour saisir les ruines ; l'escouade est forcée de quitter la Cité aux Mille Branches.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "Les quatre officières succubes ont roulé l'escouade, mais la Chasseresse de Loup Gris-Argent a déjà été vaincue : l'histoire du Chapitre 5 est complète, et tous les butins et récompenses d'achèvement sont accordés comme d'habitude.",
      "你的英雄倒下了。冒险结束。": "Votre héros a tombé. L'aventure est terminée.",
