      "选择发光的敌方目标；若有突破路线，也可以点击敌方英雄。": "Choisissez une cible ennemie brillante ; si une voie est percée, vous pouvez aussi cliquer sur le héros ennemi.",
      "武器已举起：选择敌方随从；若有突破路线，也可以攻击敌方英雄。": "Arme levée : choisissez un serviteur ennemi ; si une voie est percée, vous pouvez aussi attaquer le héros ennemi.",
