      "踏入千枝城废墟": "Entrez dans les Ruines aux Mille Branches",
      "追寻银灰狼女猎手": "Suivez la Chasseresse aux Loups Gris Argentés",
      "追寻碧露大贤者": "Cherchez le Grand Sage de la Rosée Azure",
      "踏入金麦农场": "Entrez à la Ferme du Blé d'Or",
      "会见丰穗战母": "Rencontrez la Mère de Guerre de la Moisson",
      "进军王庭": "Marchez vers la Cour",
      "挑战翠影女王": "Défiez la Reine de l'Ombre Émeraude",
      "击穿战线": "Percez la Ligne de Bataille",
      "直面狼王": "Affrontez le Roi Loup",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "Le Chapitre 5 se situe dans les ruines anciennes au sud de la Cité d'Émeraude. Les loups gris et autres bêtes étendent leur territoire avec rapidité et embuscades ; à la fin, vous affrontez la Chasseresse aux Loups Gris Argentés.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "Le Chapitre 4 a vingt nœuds de boss de limace. Ils ont une Vie épaisse, une Attaque faible et se régénèrent continuellement ; suivez le ruisseau lumineux profondément dans la forêt pour affronter le Grand Sage Nephrie de la Rosée Azure.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "Le Chapitre 3 a vingt nœuds de boss d'ours et une maison de ferme. Suivez les chemins de la ferme pour enquêter sur le village occupé, et finalement affrontez la Mère de Guerre de la Moisson Breya.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "Le Chapitre 2 a vingt nœuds de boss. Progressez le long des défenses de l'armée gobeline et finalement affrontez la Reine de l'Ombre Émeraude avec 200 de Vie.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Déployez votre armée sur quatre voies avec première ligne et seconde ligne, percez une brèche et traversez treize nœuds de la Forêt Brumeuse. Chaque victoire devient force pour la prochaine expédition.",
      "重新开始本关": "Recommencer ce Chapitre",
      "当前没有伤员": "Aucune unité blessée",
      "单机卡牌闯关冒险": "Une aventure de cartes pour un seul joueur",
