      "每项卡牌训练或救治服务均需30金币。阵亡的真实随从会进入伤员名单，救治后才能重新出战。": "Chaque entraînement de carte ou service de soin coûte 30 or. Les vrais serviteurs qui meurent vont sur la liste des blessés et doivent être soignés avant de pouvoir se battre à nouveau.",
      "⚔️ 随从训练 · 30金币": "⚔️ Entraînement du Serviteur · 30 or",
