      "前后排战线": "Première Ligne et Seconde Ligne",
      "每列前排保护后排。前后排都清空后，该路线变为突破口。": "La première ligne de chaque voie protège sa seconde ligne. Une fois que les deux sont dégagées, cette voie devient une percée.",
