      "点击同一张卡即可连续训练。面板不会关闭，每次增加2点经验并立即更新等级和进度。": "Cliquez sur la même carte pour l'entraîner à plusieurs reprises. Le panneau reste ouvert ; chaque clic ajoute 2 XP et met à jour immédiatement le niveau et la progression.",
