      "战斗经验、法力和技能成长会跨冒险保存。": "La Bataille XP, mana et la croissance de compétence se reportent entre les aventures.",
      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Autrefois capitaine de la Garde royale de la capitale. Lorsque les bêtes se sont éveillées les unes après les autres, il a jugé que protéger une seule capitale ne suffisait pas : il l'a quittée, a rassemblé sa propre escouade et est parti apaiser les troubles à travers le pays.",
      "生命上限": "Vie Max",
