      "古城废墟 · 第{0}关": "Ruines Anciennes · Étape {0}",
      "{0} · 统领试炼第{1}关": "{0} · Épreuve du Commandant {1}",
      "盖文发动「坚守」：召唤{0}个1/9训练傀儡，并自动失去5点生命（已坚持{1}/7轮）。": "Gavin utilise « Tenir Bon » : invoque {0} Mannequins d'Entraînement 1/9 et perd 5 Vie (tenu {1}/7 tours).",
      "亚瑟兰发动「天穹一闪」，命中{0}，造成10点伤害（已坚持{1}/15轮）。": "Aetherlan utilise « Éclair Céleste », frappant {0} pour 10 dégâts (tenu {1}/15 tours).",
      "女王的低语（{0}/{1}）：{2}": "Le Murmure de la Reine ({0}/{1}) : {2}",
      "{0}/7回合": "{0}/7 tours",
      "{0}/15回合": "{0}/15 tours",
      "{0}/{1}段": "{0}/{1} parties",
      "第{0}关 · {1}": "Épreuve {0} · {1}",
      "有人说{0}永远不可能被人类接纳。可我的军籍、薪饷和选票都是真的。": "Certains disent que {0} ne pourrait jamais être accepté par les humains. Pourtant, mon enrôlement, ma paie et mon vote sont tous réels.",
      "记住报名册上的名字——{0}。我来自{1}，也认同人类建立的{2}；所以我选择加入，他们也接受了我。": "Souvenez-vous du nom sur le rôle—{0}. Je viens de {1}, et je crois en la {2} que les humains ont construite ; j'ai donc choisi de me joindre, et ils m'ont accepté.",
      "记好名字，{0}。{1}。等你退场时，至少知道是谁送你的。": "Souvenez-vous du nom, {0}. {1}. Quand vous quitterez le ring, au moins vous saurez qui vous a envoyé.",
      "我是{0}，来自{1}。我的研究是{2}；而你，是今天最有价值的实战样本。": "Je suis {0}, venant de {1}. Ma recherche est {2} ; et vous êtes le plus précieux échantillon de terrain d'aujourd'hui.",
      "我是{0}，来自{1}。我信奉{2}。护卫队长，请用一场完整的战斗回应我。": "Je suis {0}, venant de {1}. Je crois en {2}. Capitaine de la Garde, réponds-moi par une bataille complète.",
      "并对同路后排造成{0}点伤害": "et inflige {0} dégâts à la seconde ligne dans la même voie",
      "同时对敌方英雄造成{0}点伤害": "et inflige {0} dégâts au héros ennemi",
      "为英雄恢复{0}点生命": "restaure {0} Vie au héros",
      "对一个敌方前排随从造成{0}点伤害{1}。": "Infligez {0} dégâts à un serviteur ennemi de première ligne{1}.",
