      "{0}在第{1}路{2}找不到合法目标，放弃本次攻击。": "{0} ne trouve pas de cible valide dans la Voie {1} {2} et abandonne cette attaque.",
      "{0}尝试召唤幼狼，但敌方战场没有空位。": "{0} essaie d'invoquer un Louveteau, mais le champ de bataille ennemi n'a pas de place libre.",
      "{0}通过「{1}」免费召唤幼狼到第{2}路{3}（1攻/2血）。": "{0} utilise « {1} » pour invoquer un Louveteau gratuitement dans la Voie {2} {3} (1/2).",
      "{0}发动「{1}」，但敌方战场已经占满。": "{0} utilise « {1} », mais le champ de bataille ennemi est déjà plein.",
      "{0}发动「{1}」：在第{2}路{3}召唤突击灰狼（4攻/1血），它可以立即攻击随从。": "{0} utilise « {1} »: invoque un Assault Grey Wolf (4/1) dans la Voie {2} {3} qui peut attaquer les serviteurs immédiatement.",
      "{0}试图召唤普通哥布林，但敌方战场已经占满。": "{0} essaie d'invoquer un gobelin ordinaire, mais le champ de bataille ennemi est déjà plein.",
      "{0}通过「{1}」免费召唤普通哥布林到第{2}路{3}（{4}攻/{5}血）。": "{0} utilise « {1} » pour invoquer un gobelin ordinaire gratuitement dans la Voie {2} {3} ({4}/{5}).",
      "{0}发动「战斗号角」：本回合召唤{1}个2攻/2血哥布林。": "{0} utilise « Cor de Bataille »: invoque {1} gobelins 2/2 ce tour.",
      "📯 战斗号角：召唤{0}个2/2哥布林": "📯 Cor de Bataille: invoquer {0} gobelins 2/2",
      "翠影女王发动「无尽绿潮」：本回合召唤{0}个普通哥布林。": "La Reine Ombre d'Émeraude utilise « Marée Verte Infinie »: invoque {0} gobelins ordinaires ce tour.",
      "👺 无尽绿潮：召唤{0}个哥布林": "👺 Marée Verte Infinie: invoquer {0} gobelins",
      "{0}召来{1}/{2}的{3}。": "{0} appelle {1}/{2} {3}.",
      "{0}发动「农垦本能」：召唤{1}个{2}/{3}巡田熊民。": "{0} utilise « Instinct Agricole »: invoque {1} Field Patrol Bears {2}/{3}.",
      "🌾 农垦本能：召唤{0}个熊族随从": "🌾 Instinct Agricole: invoquer {0} serviteurs ours",
      "，并使{0}个熊族随从获得+1/+2": "et donne aux {0} serviteurs ours +1/+2",
      "丰穗战母发动「护田战令」：召唤{0}个5/7丰穗近卫{1}。": "La Mère de Guerre de la Moisson utilise « Décret de Garde Agricole »: invoque {0} Harvest Guards 5/7{1}.",
      "🐻 护田战令：召唤{0}个丰穗近卫": "🐻 Décret de Garde Agricole: invoquer {0} Harvest Guards",
      "{0}发动「胶质再生」：首领恢复{1}点生命，{2}个史莱姆随从共恢复{3}点生命。": "{0} utilise « Régénération de Gel »: le boss restaure {1} Vie, et {2} serviteurs de gel restaurent {3} Vie au total.",
      "，并分裂出{0}个4/12碧露近卫": "et se divise en {0} Azure Dew Guards 4/12",
      "碧露大贤者发动「不灭胶质」：自身恢复{0}点生命，随从共恢复{1}点生命{2}。": "La Grande Sage de la Rosée Azure utilise « Gel Immortel »: restaure {0} Vie à elle-même et {1} Vie à ses serviteurs au total{2}.",
      "并召唤{0}名近卫": "et invoque {0} gardes",
      "🫧 不灭胶质：恢复{0}": "🫧 Gel Immortel: restaurer {0}",
      "{0}现为{1}攻": "{0} a maintenant {1} Attaque",
      "{0}个狼类随从永久获得+1攻击（{1}）。": "Les {0} serviteurs loups gagnent de façon permanente +1 Attaque ({1}).",
      "森林狼王发动「裂月咆哮」：{0}": "Le Roi Loup de la Forêt utilise « Hurlement de Lune Déchirée »: {0}",
      "五位魅魔军官撕开空间裂隙：一人带走{0}，其余四人以{1}攻/{2}血的姿态{3}。": "Les cinq officiers succubes déchirent une faille spatiale: l'un enlève {0}, tandis que les quatre autres {3} à {1}/{2}.",
      "魅魔救援结界维持到第{0}/2回合；四名军官仍站在前排，没有发动攻击。": "La barrière de sauvetage succube tient jusqu'au tour {0}/2; les quatre officiers restent toujours dans la première ligne sans attaquer.",
      "两回合已过，四位魅魔军官一同跃入裂隙，带着{0}撤离战场。": "Deux tours se sont passés; les quatre officiers succubes bondissent dans la faille ensemble, se retirant avec {0}.",
      "{0}个再生随从在回合开始时共恢复{1}点生命。": "Les serviteurs {0} avec Régénération restaurent {1} Vie au total au début du tour.",
      "我方第{0}回合开始：法力恢复为{1}/{2}，场上{3}个随从，手牌{4}张。": "Votre tour {0} commence: mana restauré à {1}/{2}, {3} serviteurs sur le terrain, {4} cartes en main.",
