      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0} a été enlevé par le cinquième officier. Les quatre officiers 10/200 scellent la première ligne et se retireront dans {1} tours.",
