      "英雄生命 {0}/{1}，同时恢复满生命": "Vie du héros {0}/{1}, également entièrement restaurée",
      "会反击": "prend une riposte",
      "无反击": "pas de riposte",
      "无法攻击": "ne peut pas attaquer",
      "罗兰·维克": "Roland Vick",
      "前王都护卫队长": "Ancien Capitaine de la Garde royale",
      "莉瑟尔": "Lisel",
      "薇奥菈": "Viola",
      "赛琳娜": "Selina",
      "格罗姆": "Grom",
      "埃尔德": "Eld",
      "奥斯坦": "Ostan",
      "希尔瓦": "Silva",
      "翠羽射手": "Archère Plume-de-jade",
      "紫晶魔女": "Sorcière d'améthyste",
      "晨曦圣女": "Sainte de l'aube",
      "裂角蛮王": "Seigneur de guerre Corne-brisée",
      "银叶游侠": "Rôdeur Feuille-d'argent",
      "银盾骑士": "Chevalier Bouclier-d'argent",
      "森灵德鲁伊": "Druide du bosquet",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "La plus jeune tireuse d'élite de la frontière forestière ; ses flèches traversent les branchages pour trouver les ennemis cachés derrière les lignes.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "Une sorcière qui a quitté la tour des mages pour étudier seule la Faille ; elle divise son mana en innombrables projectiles difficiles à esquiver.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "Une sainte envoyée au front par le Temple du Soleil, qui croit que chaque soldat mérite de se relever.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "Un seigneur de guerre des tribus du Nord qui attise la fureur de ses guerriers avec son propre sang.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Chef des rôdeurs du Bois-lune, il fait toujours surgir des archers là où l'ennemi n'en attendait aucun.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "Vétéran de l'ordre de l'Aube de la capitale ; son mur de boucliers n'a jamais reculé d'un pas.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "Une druidesse née du cœur du bosquet ancien ; chaque pousse qu'elle plante devient un arbre ancestral gardien de la forêt.",
      "穿林箭": "Flèche perçante",
      "奥术飞弹": "Projectiles arcaniques",
      "晨曦复苏": "Renouveau de l'aube",
      "血怒狂击": "Frénésie sanglante",
      "林间伏兵": "Embuscade sylvestre",
      "圣盾壁垒": "Rempart d'égide",
      "萌芽古树": "Ancien bourgeonnant",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "En ignorant la protection de la première ligne, inflige {0} dégâts à n'importe quel serviteur ennemi ; s'il meurt, piochez 1 carte.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "Tire {0} projectiles arcaniques, chacun infligeant 1 dégât à un serviteur ennemi ou au héros ennemi aléatoire.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "Rend tous leurs PV aux serviteurs alliés et rend {0} PV à votre héros.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "Votre héros perd 2 PV ; un serviteur allié gagne +{0} d'attaque ce tour et peut attaquer de nouveau immédiatement.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "Invoque un Archer Ombrefeuille à distance {0}/{1} en arrière-ligne ; il peut attaquer des serviteurs immédiatement.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "Tous les serviteurs alliés de première ligne gagnent définitivement +{0} PV ; si votre première ligne est vide, invoque un Gardien d'égide 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "Invoque une Pousse ancestrale {0}/{1} ; au début de chacun de vos tours, elle gagne définitivement +1/+1.",
      "林影弓手": "Archer Ombrefeuille",
      "圣盾卫士": "Gardien d'égide",
      "古树幼苗": "Pousse ancestrale",
      "生长": "Croissance",
      "{0}击杀了{1}，你抽1张牌。": "{0} a tué {1} ; vous piochez 1 carte.",
      "{0}枚奥术飞弹命中：{1}。": "{0} projectiles arcaniques touchent : {1}.",
      "{0}×{1}": "{0} ×{1}",
      "晨曦照亮战线：随从共恢复{0}点生命，英雄恢复{1}点生命。": "L'aube illumine la ligne : les serviteurs récupèrent {0} PV au total, votre héros {1} PV.",
      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0} entre en frénésie : son attaque passe à {1} ce tour et il peut attaquer immédiatement.",
      "{0}陷入血怒，本回合攻击力提升至{1}。": "{0} entre en frénésie : son attaque passe à {1} ce tour.",
      "圣盾壁垒加固前排：{0}个随从永久获得+{1}生命。": "Le Rempart d'égide fortifie la première ligne : {0} serviteurs gagnent définitivement +{1} PV.",
      "{0}（{1}/{2}）加入第{3}路前排。": "{0} ({1}/{2}) rejoint la première ligne de la voie {3}.",
      "{0}（{1}/{2}）加入第{3}路后排。": "{0} ({1}/{2}) rejoint l'arrière-ligne de la voie {3}.",
      "{0}株古树幼苗在回合开始时生长，获得+1/+1。": "{0} Pousse(s) ancestrale(s) grandissent au début du tour et gagnent +1/+1.",
