      "刚出炉的粗麦面包，谁都不会拒绝。": "Du pain de blé complet tout juste sorti du four. Personne ne le refuse.",
      "炭烤肉串": "Brochettes au charbon",
      "撒满辣椒粉的炭烤肉串，哥布林最爱抢着吃。": "Des brochettes grillées couvertes de piment. Les gobelins se les arrachent.",
      "金蜜松饼": "Crêpes épaisses au miel doré",
      "淋上整勺蜂蜜的厚松饼，熊族闻到就走不动路。": "D'épaisses crêpes nappées de miel. Le peuple ours s'arrête net rien qu'à l'odeur.",
      "月露果冻": "Gelée de rosée lunaire",
      "用月潭露水凝成的清凉果冻，史莱姆会把它整个吞进身体里。": "Une gelée fraîche prise avec la rosée du Bassin lunaire. Les slimes l'avalent tout entière.",
      "炙烤带骨肉": "Rôti sur l'os",
      "外焦里嫩的大块带骨肉，狼族会一边啃一边摇尾巴。": "Un gros rôti sur l'os, croustillant dehors et tendre dedans. Les loups remuent la queue en le rongeant.",
      "猎人炖锅": "Ragoût du chasseur",
      "炖了一整夜的浓汤，暖胃也暖心。": "Un ragoût épais mijoté toute la nuit. Il réchauffe le ventre et le cœur.",
      "丰收宴席": "Festin de la moisson",
      "一整桌丰盛的宴席，再倔强的俘虏也会动摇。": "Une table entière de mets copieux. Même le prisonnier le plus têtu vacille.",
      "下矿": "Mine",
      "钻进褐石矿坑挖金子，按好感等级带回金币。": "Creuse l'or dans les mines de Pierrebrune et rapporte des pièces selon le niveau de lien.",
      "种田": "Labour",
      "去营地外的麦田耕种，收获的麦子直接磨成面粉，补充队伍粮食。": "Cultive les champs de blé hors du camp ; la récolte est moulue en farine pour les rations du groupe.",
      "熬药": "Distillation",
      "用身体慢慢熬出药水，给卡组里随机一张未满级的卡牌增加经验。": "Distille lentement une potion dans son propre corps et donne de l'XP à une carte aléatoire de votre deck qui n'est pas au niveau max.",
      "打猎": "Chasse",
      "去林子里打猎，带回炙烤带骨肉（狼族最爱）和一些粮食。": "Chasse dans les bois et rapporte du Rôti sur l'os (le préféré des loups) et quelques rations.",
