      "典狱长·艾德琳": "Adeline la geôlière",
      "钥匙在我腰上，猫在我头上。放心，这里没有一只跑得出去——也没有一只想跑。": "Les clés à la ceinture, le chat sur la tête. Tranquille : aucun ne peut s'échapper d'ici — et aucun n'en a envie.",
