      "🍽️ 餐馆 · 新开业": "🍽️ Restaurant · Nouvelle ouverture",
      "出售各式菜肴。带去营地监狱投喂在押首领，提升好感度，结缘后才能使用它们的卡牌。": "Vend toutes sortes de plats. Apportez-les à la prison du camp pour nourrir les boss captifs et augmenter leur affinité ; leurs cartes ne sont utilisables qu'une fois liés.",
