      "四家店铺各有分工：装备店可将战场缴获的粗糙武器重锻为更高品质；金杯餐馆出售面粉与各式菜肴；赤龙客栈可以住一晚，直接进入第二天。": "Quatre boutiques, chacune son métier : l'Armurerie reforge les armes grossières du champ de bataille en meilleures armes ; le Restaurant de la Coupe d'Or vend farine et plats ; l'Auberge du Dragon Rouge vous laisse dormir jusqu'au lendemain.",
