      "每战-{0} · 每天-{1}": "-{0}/combat · -{1}/jour",
      "每场战斗消耗：随从{0} + 犯人{1} = {2}份粮食；每天日常消耗{3}场的量，共{4}份": "Chaque combat consomme : serviteurs {0} + prisonniers {1} = {2} rations. La consommation quotidienne équivaut à {3} combats, soit {4} rations",
      "现实{0}分钟为游戏里的一天；新的一天可以再投喂每名在押首领一次，队伍会吃掉{1}场战斗的粮食。": "{0} minutes réelles font un jour de jeu. Chaque nouveau jour, vous pouvez nourrir encore une fois chaque boss captif, et le groupe mange les rations de {1} combats.",
      "第{0}天": "Jour {0}",
      "🌙 第{0}天夜里 · 营地监狱": "🌙 Nuit du jour {0} · Prison du camp",
      "🌙 夜晚事件": "🌙 Événement nocturne",
      "好的": "D'accord",
      "第{0}天：粮食不够日常所需（{1}份），库存已经吃光了。快去金杯餐馆买面粉！": "Jour {0} : pas assez de rations pour la journée ({1}) ; les réserves sont vides. Achetez de la farine au Restaurant de la Coupe d'Or !",
      "第{0}天开始：队伍吃掉了{1}份日常口粮，在押首领又可以投喂了。": "Début du jour {0} : le groupe a mangé {1} rations quotidiennes, et les boss captifs peuvent de nouveau être nourris.",
      "粮食不足，队伍饿着肚子出战：本场我方随从攻击-1。": "Rations insuffisantes : le groupe combat le ventre vide, vos serviteurs ont -1 d'Attaque pour ce combat.",
      "花{0}金币买面粉并出战": "Dépenser {0} or en farine et combattre",
      "金币不足（需要{0}）": "Pas assez d'or ({0} requis)",
      "队伍补给": "Ravitaillement du groupe",
      "🌾 粮食不足": "🌾 Rations insuffisantes",
