      "份粮食（出战随从 {0} + 在押犯人 {1}），现有": "rations (serviteurs {0} + prisonniers {1}). Vous en avez",
      "份。": ".",
      "{0}{1}每袋{2}金币、可供{3}人吃一顿。补足需要{4}袋，共{5}金币。": "{0}{1} : {2} or le sac, nourrit {3} pour un repas. Il faut {4} sacs, soit {5} or.",
