      "🔒 进入营地监狱": "🔒 Entrer dans la prison du camp",
      "第{0}关": "Chapitre {0}",
      "第{0}关 · 精英": "Chapitre {0} · Élite",
      "🍽️ 今日已喂": "🍽️ Nourri aujourd'hui",
      "探望{0}": "Rendre visite à {0}",
      "{0} ·「{1}」": "{0} · « {1} »",
      "未解锁 · 第{0}关已结缘 {1}/{2}": "Verrouillée · Chapitre {0} liés {1}/{2}",
      "最终首领卡牌": "Cartes de boss final",
      "牢房还空着。击败冒险中的首领，它们就会被押回这里。": "Les cellules sont vides. Battez des boss pendant vos aventures et ils seront ramenés ici.",
      "已关押 {0}/{1} 名觉醒者。各关的最终首领不在此列：森林狼王战死于密林，其余首领都在最后关头被同族救走。": "{0}/{1} Éveillés emprisonnés. Les boss finaux de chaque chapitre n'en font pas partie : le Roi-Loup de la forêt est tombé au fond des bois, et les autres ont été sauvés par les leurs au dernier moment.",
      "第二关起击败的首领，其首杀奖励卡要与牢里的本人结缘（好感度{0}）后才能出战；继续投喂，每{1}点好感升一级（最高{2} Lv{3}），结缘后每高一级：随从+{4}攻击、+{5}生命，法术效果提升{6}级。最终首领的卡牌要等本关全部在押首领结缘才能使用，等级取其中最低的一位。每名首领每天（现实{7}分钟）只能投喂一次，距离新的一天还有{8}。背包里共有 {9} 份食物。": "À partir du chapitre 2, la carte de récompense de première victoire d'un boss n'est utilisable qu'après vous être lié à lui en prison (affinité {0}). Continuez à le nourrir pour gagner un niveau toutes les {1} d'affinité (max {2} Niv{3}). Chaque niveau au-delà de Lié donne aux serviteurs +{4} d'Attaque et +{5} de Vie, et aux sorts +{6} niveaux d'effet. La carte d'un boss final se débloque quand tous les boss captifs du chapitre sont liés et prend le plus bas de leurs niveaux. Chaque boss ne mange qu'une fois par jour ({7} minutes réelles) ; le nouveau jour commence dans {8}. Vous avez {9} aliments dans votre sac.",
      "📖 族群往事": "📖 Récits des clans",
      "前往城镇商店": "Aller aux boutiques de la ville",
      "返回队伍营地": "Retour au Camp de l'Équipe",
      "后回营": " avant le retour",
      "✅ 今日已干活": "✅ A travaillé aujourd'hui",
      "{0} 结缘Lv1：{1}；誓约Lv5：{2}": "{0} Lié Niv1 : {1} ; Juré Niv5 : {2}",
      "派遣劳动": "Corvées",
      "结缘后的首领每天可以派出去干一次活，{0}小时（现实{1}分钟）后带着收获回营；干活期间不能投喂。可派 {2} 名 · 在外 {3} 名": "Les boss liés peuvent partir travailler une fois par jour et reviennent avec leur butin après {0} heures ({1} minutes réelles). On ne peut pas les nourrir pendant ce temps. Disponibles : {2} · Dehors : {3}",
      "一键派遣（{0}）": "Tout envoyer ({0})",
