      "{0}出发去{1}了，{2}小时后回营。": "{0} est parti ({1}) ; retour dans {2} heures.",
      "没有可以派遣的首领：需要已结缘、今天还没干过活且在牢里。": "Aucun boss à envoyer : il doit être lié, dans sa cellule et ne pas avoir travaillé aujourd'hui.",
      "派出了{0}名首领去干活，{1}小时后回营。": "{0} boss envoyés au travail ; retour dans {1} heures.",
      "未结缘 · 需第{0}关全部在押首领结缘（{1}/{2}）": "Non lié · Nécessite de se lier à tous les boss captifs du chapitre {0} ({1}/{2})",
      "未结缘 · 需在营地监狱与{0}结缘（好感度 {1}/{2}）": "Non lié · Liez-vous à {0} dans la prison du camp (affinité {1}/{2})",
      "好感 +{0}": "Affinité +{0}",
      "好感 +{0} · 最爱": "Affinité +{0} · Préféré",
      "结缘后才能使用卡牌「{0}」。": "Liez-vous pour débloquer la carte « {0} ».",
      "卡牌「{0}」已可出战。": "La carte « {0} » peut combattre.",
      "卡牌「{0}」已可出战，当前加成 {1}。": "La carte « {0} » peut combattre ; bonus actuel {1}.",
